<div class="sign-in-page vh-100" style="background-image: url(./assets/images/pages/01.webp); background-size: cover; background-repeat: no-repeat;">
 <div class="container">
  <div class="row justify-content-center align-items-center height-self-center vh-100">
    <div class="col-lg-8 col-md-12 align-self-center">
      <div class="user-login-card rounded-3">
        <a href="./index.html">
          <img class="img-fluid logo" src="./assets/images/logo.png" alt="Logo">
        </a>
        <div class="sign-in-page-data">
          <h4 class="text-center mb-5">Create Your Account</h4>

          <form id="register-form">

            <div class="row row-cols-1 row-cols-lg-2 g-2 g-lg-5">

              <div class="col">
                <label for="first-name" class="mb-2 custom-form-label">First Name</label>
                <input type="text" id="first-name" name="firstName" class="form-control mb-0">
                <div class="invalid-feedback"></div>
              </div>

              <div class="col">
                <label for="last-name" class="mb-2 custom-form-label">Last Name</label>
                <input type="text" id="last-name" name="lastName" class="form-control mb-0">
                <div class="invalid-feedback"></div>
              </div>

              <div class="col">
                <label for="username" class="mb-2 custom-form-label">Username *</label>
                <input type="text" id="username" name="username" class="form-control mb-0" required>
                <div class="invalid-feedback">Please choose a username.</div>
              </div>

              <div class="col">
                <label for="email" class="mb-2 custom-form-label">Email *</label>
                <input type="email" id="email" name="email" class="form-control mb-0" required>
                <div class="invalid-feedback">Please enter a valid email.</div>
              </div>

              <div class="col">
                <label for="password" class="mb-2 custom-form-label">Password *</label>
                <div class="input-group custom-input-group mb-3">
                  <input placeholder="Password" required type="password" id="password" name="password"
                    class="mb-0 form-control">
                  <span class="input-group-text"><i class="ph ph-eye-slash" id="togglePassword1"></i></span>
                </div>
                <div class="invalid-feedback">Password must be at least 8 characters.</div>
              </div>

              <div class="col">
                <label for="confirm-password" class="mb-2 custom-form-label">Confirm Password *</label>
                <div class="input-group custom-input-group mb-3">
                  <input placeholder="Confirm Password" required type="password" id="confirm-password"
                    name="confirmPassword" class="mb-0 form-control">
                  <span class="input-group-text"><i class="ph ph-eye-slash" id="togglePassword2"></i></span>
                </div>
                <div class="invalid-feedback">Passwords do not match.</div>
              </div>

            </div> <label class="list-group-item d-flex align-items-center mt-5 mb-3 text-white">
              <input class="form-check-input m-0 me-2" type="checkbox" id="terms" name="terms" required>
              I've read and accept the <a href="terms-of-use.html" class="ms-1">terms &amp; conditions*</a>
              <div class="invalid-feedback" style="margin-left: 1.5rem;">You must agree to the terms.</div>
            </label>

            <div class="row text-center">
              <div class="col-lg-3"></div>
              <div class="col-lg-6">
                <div class="full-button">

                  <div id="form-message" class="mb-3"></div>

                  <button type="submit" id="signup-button"
                    class="btn btn-primary text-capitalize position-relative w-100 my-3 rounded-3">
                    <span class="button-text">Sign Up</span>
                    <span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"
                      style="display: none;"></span>
                  </button>

                  <p class="mt-2 mb-0 fw-normal">Already have an account?<a href="/login" class="ms-1">Login</a>
                  </p>
                </div>
              </div>
              <div class="col-lg-3"></div>
            </div>

          </form>
          </div>
      </div>
    </div>
  </div>
</div>
