<script>
    // Wait for the HTML document to finish loading
document.addEventListener("DOMContentLoaded", () => {

  // === 1. Select all the elements we need ===
  const registerForm = document.querySelector("#register-form");
  const signupButton = document.querySelector("#signup-button");
  const buttonText = signupButton.querySelector(".button-text");
  const loadingSpinner = signupButton.querySelector(".spinner-border");

  // Input fields
  const firstNameInput = document.querySelector("#first-name");
  const lastNameInput = document.querySelector("#last-name");
  const usernameInput = document.querySelector("#username");
  const emailInput = document.querySelector("#email");
  const passwordInput = document.querySelector("#password");
  const confirmPasswordInput = document.querySelector("#confirm-password");
  const termsInput = document.querySelector("#terms");

  // Password toggle icons
  const togglePassword1 = document.querySelector("#togglePassword1");
  const togglePassword2 = document.querySelector("#togglePassword2");

  // === 2. Helper functions for showing/clearing errors ===
  
  /**
   * Shows a validation error message for a specific input field.
   * @param {HTMLElement} inputElement - The <input> element.
   * @param {string} message - The error message to display.
   */
  function showError(inputElement, message) {
    inputElement.classList.add("is-invalid"); 
    let errorElement;
    
    if (inputElement.type === 'checkbox') {
      errorElement = inputElement.closest('label').querySelector('.invalid-feedback');
      if (errorElement) {
        errorElement.style.display = 'block'; 
      }
    } else if (inputElement.closest('.input-group')) {
      errorElement = inputElement.closest('.col').querySelector('.invalid-feedback');
    } else {
      errorElement = inputElement.closest('.col').querySelector('.invalid-feedback');
    }
    
    if (errorElement) {
      errorElement.textContent = message;
    }
  }

  /**
   * Clears all validation error messages and borders.
   */
  function clearErrors() {
    registerForm.querySelectorAll(".is-invalid").forEach((input) => {
      input.classList.remove("is-invalid");
    });
    
    const termsError = termsInput.closest("label").querySelector(".invalid-feedback");
    if (termsError) {
      termsError.style.display = "none";
    }
  }
  
  /**
   * Toggles the loading state of the submit button
   * @param {boolean} isLoading - Whether to show the loading state
   */
  function setButtonLoading(isLoading) {
    signupButton.disabled = isLoading;
    buttonText.style.display = isLoading ? "none" : "inline-block";
    loadingSpinner.style.display = isLoading ? "inline-block" : "none";
  }

  /**
   * Checks password strength.
   * @param {string} password - The password to check.
   * @returns {object} - An object { isValid: boolean, message: string }
   */
  function checkPasswordStrength(password) {
    if (password.length < 8) {
      return { isValid: false, message: "Password must be at least 8 characters long." };
    }
    if (!/[a-z]/.test(password)) {
      return { isValid: false, message: "Password must contain at least one lowercase letter." };
    }
    if (!/[A-Z]/.test(password)) {
      return { isValid: false, message: "Password must contain at least one uppercase letter." };
    }
    if (!/\d/.test(password)) { 
      return { isValid: false, message: "Password must contain at least one number." };
    }
    if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
      return { isValid: false, message: "Password must contain at least one special character." };
    }
    return { isValid: true, message: "Password strength is good." };
  }

  /**
   * === NEW: Set up password toggle functionality ===
   */
  function setupPasswordToggle() {
    // Listener for the first password field
    togglePassword1.addEventListener('click', () => {
      // Toggle the 'type' attribute
      const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
      passwordInput.setAttribute('type', type);
      
      // Toggle the icon class
      togglePassword1.classList.toggle('ph-eye');
      togglePassword1.classList.toggle('ph-eye-slash');
    });

    // Listener for the second password field
    togglePassword2.addEventListener('click', () => {
      const type = confirmPasswordInput.getAttribute('type') === 'password' ? 'text' : 'password';
      confirmPasswordInput.setAttribute('type', type);
      
      togglePassword2.classList.toggle('ph-eye');
      togglePassword2.classList.toggle('ph-eye-slash');
    });
  }

  // === 3. Main validation function (Client-side) ===
  function validateForm() {
    let isValid = true;
    const errors = [];
    clearErrors(); 

    // Get all values
    const firstName = firstNameInput.value.trim();
    const lastName = lastNameInput.value.trim();
    const username = usernameInput.value.trim();
    const email = emailInput.value.trim();
    const password = passwordInput.value.trim();
    const confirmPassword = confirmPasswordInput.value.trim();
    const terms = termsInput.checked;

    // --- Start Validation Checks ---
    if (firstName && !/^[a-zA-Z\-']+$/.test(firstName)) {
      const message = "First name can only contain letters, hyphens, or apostrophes.";
      errors.push({ field: "first-name", message: message });
      showError(firstNameInput, message);
      isValid = false;
    }
    if (lastName && !/^[a-zA-Z\-']+$/.test(lastName)) {
      const message = "Last name can only contain letters, hyphens, or apostrophes.";
      errors.push({ field: "last-name", message: message });
      showError(lastNameInput, message);
      isValid = false;
    }
    if (username === "") {
      const message = "Please choose a username.";
      errors.push({ field: "username", message: message });
      showError(usernameInput, message);
      isValid = false;
    }
    if (email === "") {
      const message = "Please enter your email address.";
      errors.push({ field: "email", message: message });
      showError(emailInput, message);
      isValid = false;
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      const message = "Please enter a valid email address.";
      errors.push({ field: "email", message: message });
      showError(emailInput, message);
      isValid = false;
    }

    const strengthCheck = checkPasswordStrength(password);
    if (!strengthCheck.isValid) {
      errors.push({ field: "password", message: strengthCheck.message });
      showError(passwordInput, strengthCheck.message);
      isValid = false;
    }
    if (confirmPassword === "") {
      const message = "Please confirm your password.";
      errors.push({ field: "confirm-password", message: message });
      showError(confirmPasswordInput, message);
      isValid = false;
    } else if (password !== confirmPassword) {
      const message = "Passwords do not match.";
      errors.push({ field: "confirm-password", message: message });
      showError(confirmPasswordInput, message);
      isValid = false;
    }
    if (!terms) {
      const message = "You must agree to the terms and conditions.";
      errors.push({ field: "terms", message: message });
      showError(termsInput, message);
      isValid = false;
    }

    if (!isValid) {
      console.warn("Validation failed. Errors:", errors);
    } else {
      console.log("Client-side validation passed.");
    }
    
    return isValid;
  }

  // === 4. Add the submit event listener to the form ===
  registerForm.addEventListener("submit", async (event) => {
    event.preventDefault(); 

    const isFormValid = validateForm();
    if (!isFormValid) {
      return; 
    }

    setButtonLoading(true);

    const formData = {
      firstName: firstNameInput.value.trim(),
      lastName: lastNameInput.value.trim(),
      username: usernameInput.value.trim(),
      email: emailInput.value.trim(),
      password: passwordInput.value.trim()
    };

    try {
      const response = await fetch('/register-backend', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      const data = await response.json();

      if (response.ok) {
        // === MODIFIED: Show SUCCESS Toast ===
        Toastify({
          text: data.message,
          duration: 3000,
          close: true,
          gravity: "top", 
          position: "right",
          style: {
            background: "linear-gradient(to right, #00b09b, #96c93d)", // Green gradient
          }
        }).showToast();
        registerForm.reset(); // Clear all the input fields
        
      } else {
        // === MODIFIED: Show ERROR Toast (for server errors) ===
        if (data.field) {
          if (data.field === 'email') {
            showError(emailInput, data.message);
          } else if (data.field === 'username') {
            showError(usernameInput, data.message);
          } else {
            Toastify({
              text: data.message,
              duration: 3000,
              close: true,
              gravity: "top",
              position: "right",
              style: {
                background: "linear-gradient(to right, #ff5f6d, #ffc371)", // Red gradient
              }
            }).showToast();
          }
        } else {
          Toastify({
            text: data.message || 'An unknown error occurred.',
            duration: 3000,
            close: true,
            gravity: "top",
            position: "right",
            style: {
              background: "linear-gradient(to right, #ff5f6d, #ffc371)", // Red gradient
            }
          }).showToast();
        }
      }

    } catch (error) {
      // === MODIFIED: Show ERROR Toast (for network errors) ===
      console.error('Registration failed:', error);
      Toastify({
        text: 'Could not connect to the server. Please try again.',
        duration: 3000,
        close: true,
        gravity: "top",
        position: "right",
        style: {
          background: "linear-gradient(to right, #ff5f6d, #ffc371)", // Red gradient
        }
      }).showToast();
    
    } finally {
      setButtonLoading(false);
    }
  });

  // === 5. Activate the password toggles ===
  setupPasswordToggle();

});
</script>